pragma solidity >=0.8.4 <0.9;

import {IComposeReceiverAccountBase} from "./IComposeReceiverAccountBase.sol";
import {IPersonalAccountBase} from "./IPersonalAccountBase.sol";

/// @dev Execute action: `actionData` is `abi.encode(bytes32 operationId, uint64 deadline,
/// Call[] calls)`. Executes the signed calls from this account in order and atomically for
/// calls that revert - the remote form of the Flare `executeUserOp`, carried by the
/// authenticated compose instead of the controller, with the user's XRPL signature covering
/// every target, value and calldata. Return data is not interpreted, matching Flare's
/// `executeUserOp`: a callee that reports failure by returning `false` (some ERC-20s) or a
/// codeless target counts as a successful call, so the wallet must know the callee's success
/// convention.
uint8 constant PA_ACTION_EXECUTE = 1;

/**
 * @title IPersonalAccountRemote
 * @notice User interface for the remote Personal Account: the implementation
 * registered behind the frozen PA proxy on a diamond other than Flare's (the loan chain,
 * Ethereum, at launch),
 * living at the same CREATE2 address as the user's Flare Personal Account. It has no local
 * owner and no controller-driven methods — instructions exist only on Flare — so every
 * authorized action arrives as an authenticated LayerZero compose message sent by this same
 * account on Flare (`sendCrossChainUserOp`). The action set is exactly one action: execute
 * a signed batch of calls, the way the Flare account executes `executeUserOp`. The blast
 * radius is therefore the same as a controller compromise on Flare: a compromised compose
 * root has the full on-chain authority of this address - balances, approvals, external
 * positions and any role granted to it - and over the loan subaccount no direct authority at
 * all: it has no parent-callable method, so Morpho collateral and debt stay behind the
 * subaccount's own compose authentication. There is
 * no permissionless rail: what arrives here (borrow proceeds the user directed here,
 * recovered loan-token surplus, strays, native delivered with a message to fund
 * value-carrying calls) moves only by the user's signature.
 */
interface IPersonalAccountRemote is IPersonalAccountBase, IComposeReceiverAccountBase {
    /// @notice One call of a signed batch. Field-identical to the Flare `IPersonalAccount.Call`
    /// (the sender encodes that struct, this account decodes this one - the same ABI layout).
    struct Call {
        /// @notice Target contract or recipient.
        address target;
        /// @notice Native value (in wei) to send with the call, from this account's balance.
        uint256 value;
        /// @notice Call data; empty for a plain native transfer.
        bytes data;
    }

    /**
     * @notice Emitted when a signed batch of calls executed.
     * @param operationId The user-chosen operation id, now consumed.
     * @param callCount The number of calls executed.
     * @param guid The LayerZero message id the action arrived with.
     */
    event UserOpExecuted(
        bytes32 operationId,
        uint256 callCount,
        bytes32 guid
    );

    /**
     * @notice Emitted when an authenticated action completes without executing.
     * @param operationId The payload's operation id. A duplicate was already consumed; an
     * expired skip leaves it unconsumed (the intent can retry under it).
     * @param reason The skip reason (see the `SKIP_REASON_*` constants).
     * @param guid The LayerZero message id the action arrived with.
     */
    event ActionSkipped(
        bytes32 operationId,
        uint8 reason,
        bytes32 guid
    );

    /**
     * @notice Reverts on an empty batch, which would only consume the operation id.
     */
    error EmptyUserOp();

    /**
     * @notice Reverts if a call of the batch fails: the whole delivery reverts (all or
     * nothing) and stays retriable at the endpoint, with the id unconsumed.
     * @param index The index of the call that failed.
     * @param returnData The return data of the failed call.
     */
    error CallFailed(
        uint256 index,
        bytes returnData
    );

    /**
     * @notice Reverts on the implementation contract itself, which is never initialized: it
     * must not accept native, since nothing could ever move it out again.
     */
    error NotInitialized();
}

contracts/userInterfaces/ISubaccount.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

import {IControlledAccount} from "./IControlledAccount.sol";

/**
 * @title ISubaccount
 * @notice The type-generic subaccount surface every implementation must expose. The frozen
 * `SubaccountProxy` creation code embeds `initialize`'s exact selector and delegate-calls
 * it from the proxy constructor, so a new subaccount type is not merely "any contract with a
 * registered implementation": its implementation must implement this interface. Only the
 * initializer's ABI is frozen with the proxy creation code — changing it shifts every predicted
 * subaccount address; the rest of this interface is the protocol's requirement on every
 * implementation, not something the proxy embeds.
 */
interface ISubaccount is IControlledAccount {

    /**
     * @notice Emitted when a subaccount is initialized.
     * @param controllerAddress The controller address.
     * @param parentPersonalAccount The parent Personal Account address (the same address on
     * every chain; codeless on a remote chain until its remote Personal Account is created).
     * @param subaccountType The subaccount type.
     */
    event SubaccountInitialized(
        address indexed controllerAddress,
        address indexed parentPersonalAccount,
        uint256 indexed subaccountType
    );

    /**
     * @notice Reverts if the parent Personal Account address is invalid (zero).
     */
    error InvalidParentPersonalAccount();

    /**
     * @notice Reverts if a parent-driven method is called by anything other than the parent
     * Personal Account (on a remote chain, the remote Personal Account executing the user's
     * signed cross-chain user operation).
     */
    error OnlyParent();

    /**
     * @notice Initializes the subaccount. Delegate-called by the subaccount proxy's
     * constructor; implementations must reject re-initialization and lock the implementation
     * contract itself in their own constructor.
     * @param _controllerAddress MasterAccountController address.
     * @param _parentPersonalAccount Parent Personal Account address.
     * @param _subaccountType The subaccount type.
     */
    function initialize(
        address _controllerAddress,
        address _parentPersonalAccount,
        uint256 _subaccountType
    )
        external;

    /**
     * @notice Returns the parent Personal Account address for this subaccount.
     * @return The parent Personal Account address.
     */
    function parentPersonalAccount()
        external view
        returns (address);

    /**
     * @notice Returns the subaccount type.
     * @return The subaccount type.
     */
    function subaccountType()
        external view
        returns (uint256);

    /**
     * @notice Returns the implementation address of the subaccount.
     * @return The implementation address.
     */
    function implementation()
        external view
        returns (address);
}

contracts/userInterfaces/facets/IBridgeR.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

/**
 * @title IBridgeRoutesFacet
 * @notice Interface for the BridgeRoutesFacet contract: the Flare-side, governance-set routing
 * for everything that bridges FXRP or sends a compose message from an account here to that same
 * account's address on a remote chain — the subaccounts of every type and the Personal Account's
 * cross-chain user operations. Three records: the one FXRP OFT adapter on Flare, one pinned peer
 * per remote chain (a route), and the remote chain each subaccount type lives on. The Flare
 * counterpart of the remote diamonds' {IComposeTransportFacet}: a transport says how composes
 * arrive on a remote, a route says where sends go from here. Cut only on the Flare diamond.
 * @dev Routes are governance-set rather than supplied by the caller, so that no caller can choose
 * where assets are bridged: a subaccount's destination is the route of its type, and a Personal
 * Account's cross-chain user operation names a destination endpoint that must be a registered
 * route. Every send also re-checks the OFT's live peer for the destination against the pinned one,
 * so a peer mutation on the adapter after configuration fails the sends closed instead of routing
 * to an unknown remote OApp.
 */
interface IBridgeRoutesFacet {

    /**
     * @notice Emitted when the FXRP OFT adapter is set or cleared.
     * @param fxrpOft The FXRP OFT adapter; zero when cleared.
     */
    event FxrpOftSet(
        address fxrpOft
    );

    /**
     * @notice Emitted when a route is set or cleared.
     * @param destinationEid The LayerZero endpoint id of the remote chain.
     * @param destinationPeer The pinned peer on that chain; zero when the route is cleared.
     */
    event BridgeRouteSet(
        uint32 destinationEid,
        bytes32 destinationPeer
    );

    /**
     * @notice Emitted when a subaccount type is pinned to the remote chain it lives on. Once,
     * per type: the pin is write-once. Only the types that bridge get one; a Flare-local type
     * (a vault subaccount, say) never does.
     * @param subaccountType The subaccount type.
     * @param destinationEid The route's endpoint id.
     */
    event SubaccountTypeRouteSet(
        uint256 subaccountType,
        uint32 destinationEid
    );

    /**
     * @notice Emitted when a pinned type's route is suspended or resumed.
     * @param subaccountType The subaccount type.
     * @param suspended Whether the type's forward moves are now blocked.
     */
    event SubaccountTypeRouteSuspended(
        uint256 subaccountType,
        bool suspended
    );

    /**
     * @notice Reverts if the FXRP OFT address is invalid: not a contract, not wrapping FXRP, not
     * sharing its decimals, or reporting a non-canonical interface/message-codec version.
     */
    error InvalidFxrpOft();

    /**
     * @notice Reverts if a route is set while no FXRP OFT adapter is configured.
     */
    error FxrpOftNotConfigured();

    /**
     * @notice Reverts if the destination endpoint id is zero.
     */
    error InvalidDestinationEid();

    /**
     * @notice Reverts if the destination peer has dirty upper bits (not a clean zero-padded EVM
     * address), or does not match the OFT's live peer for the destination endpoint.
     */
    error InvalidDestinationPeer();

    /**
     * @notice Reverts an attempt to re-point a subaccount type at a different chain. The pin is
     * write-once: the type is the (chain, product) identity its positions live under, and its
     * signed instructions carry no destination, so re-pointing would route an already-signed
     * action to another chain. A second chain is a second type; to stop a pinned type's
     * forward moves, suspend it.
     * @param subaccountType The subaccount type.
     * @param destinationEid The endpoint id it is already pinned to.
     */
    error SubaccountTypeRoutePinned(
        uint256 subaccountType,
        uint32 destinationEid
    );

    /**
     * @notice Reverts if a subaccount type is first pinned to an endpoint id that has no route,
     * or (with a zero id) if an unpinned type is suspended.
     * @param destinationEid The unregistered endpoint id.
     */
    error UnknownBridgeRoute(
        uint32 destinationEid
    );

    /**
     * @notice Returns the FXRP OFT adapter every route sends through.
     * @return The adapter; zero when not configured.
     */
    function getFxrpOft()
        external view
        returns (address);

    /**
     * @notice Returns the pinned peer of a route.
     * @param _destinationEid The LayerZero endpoint id of the remote chain.
     * @return The pinned peer on that chain; zero when no route exists for the endpoint.
     */
    function getBridgeRoute(
        uint32 _destinationEid
    )
        external view
        returns (bytes32);

    /**
     * @notice Returns every registered route.
     * @dev The order is unspecified (clearing a route swaps the last one into its place); the
     * two arrays are index-aligned.
     * @return _destinationEids The endpoint ids.
     * @return _destinationPeers The pinned peers, aligned with `_destinationEids`.
     */
    function getBridgeRoutes()
        external view
        returns (uint32[] memory _destinationEids, bytes32[] memory _destinationPeers);

    /**
     * @notice Returns the route a subaccount type bridges over, if it bridges at all.
     * @dev The tuple a subaccount needs to send and to authenticate its own bridge-back: the
     * adapter, the endpoint id its type is pinned to, and that route's pinned peer. Any zero
     * member means the type is not routable right now (no adapter, a type never pinned, a
     * cleared route, or a suspended type - a suspension answers as a zero endpoint id, while
     * the pin itself survives in {getSubaccountTypeRoutePin}).
     * @param _subaccountType The subaccount type.
     * @return _fxrpOft The FXRP OFT adapter.
     * @return _destinationEid The endpoint id of the type's remote chain.
     * @return _destinationPeer The pinned peer there.
     */
    function getSubaccountTypeRoute(
        uint256 _subaccountType
    )
        external view
        returns (address _fxrpOft, uint32 _destinationEid, bytes32 _destinationPeer);

    /**
     * @notice Returns a subaccount type's write-once chain pin and whether it is suspended.
     * @dev For governance and tooling: {getSubaccountTypeRoute} answers "can this type send
     * now", which a suspension turns to zero; this one still shows where the type's positions
     * live. A zero endpoint id means the type was never pinned.
     * @param _subaccountType The subaccount type.
     * @return _destinationEid The endpoint id the type is pinned to, or zero.
     * @return _suspended Whether the type's forward moves are suspended.
     */
    function getSubaccountTypeRoutePin(
        uint256 _subaccountType
    )
        external view
        returns (uint32 _destinationEid, bool _suspended);
}

contracts/userInterfaces/facets/ICompose.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

/**
 * @title IComposeTransportFacet
 * @notice The compose transport of a remote diamond: one record per diamond naming the
 * LayerZero endpoint that may call `lzCompose`, the OFT that must be the compose sender, the
 * origin chain and the pinned peer there. Every compose receiver on the diamond — the remote
 * Personal Account and every remote subaccount type — authenticates against it, so it is the
 * security root of every action that arrives without a local signature. One route per
 * diamond: a token bridged through a different OFT would need a transport per route, which is
 * a schema change, not a setting. Cut only on remote diamonds (the loan chain, Ethereum, at
 * launch).
 * @dev The transport is written under the timelock and cleared immediately: the clear is the
 * containment lever for a compromised endpoint, OFT or peer, and a lever behind a timelock is
 * not one. The clear does not cancel queued `setComposeTransport` calls (the timelock keys them
 * by calldata hash and lets anyone execute a matured one - cancel them first), and it does not
 * retire compose packets already queued at the endpoint (a delivery that reverts against a
 * cleared transport stays retriable). The incident runbook is therefore: pause, cancel queued
 * transport sets, clear, and later set a replacement transport that rotates the compromised
 * identity - the exact compromised tuple is never restored, or packets forged under it would
 * pass authentication again.
 */
interface IComposeTransportFacet {

    /// @dev The compose transport: how authenticated actions arrive and, for the remote loan
    /// subaccount, how the bridge-back leaves. One per diamond, shared by every compose
    /// receiver on it.
    struct Transport {
        /// @notice The LayerZero EndpointV2: the only allowed `lzCompose` caller.
        address lzEndpoint;
        /// @notice The OFT on this chain: the only allowed compose sender (`_from`), the
        /// authoritative identity of the bridged token (`token()`), and the vehicle of the
        /// bridge-back.
        address oft;
        /// @notice The LayerZero endpoint id of the origin chain (Flare).
        uint32 originEid;
        /// @notice The pinned peer on the origin chain (the Flare-side OFT adapter); the
        /// bridge-back re-checks the live peer against it on every call.
        bytes32 originPeer;
    }

    /**
     * @notice Emitted when the compose transport is set.
     * @param lzEndpoint The LayerZero endpoint.
     * @param oft The OFT.
     * @param originEid The origin (Flare) endpoint id.
     * @param originPeer The pinned origin peer.
     */
    event ComposeTransportSet(
        address lzEndpoint,
        address oft,
        uint32 originEid,
        bytes32 originPeer
    );

    /**
     * @notice Emitted when the compose transport is cleared.
     */
    event ComposeTransportCleared();

    /**
     * @notice Reverts if the LayerZero endpoint is not a contract, or is not the endpoint the
     * OFT is wired to.
     */
    error InvalidLzEndpoint();

    /**
     * @notice Reverts if the origin endpoint id is zero.
     */
    error InvalidOriginEid();

    /**
     * @notice Reverts if the origin peer is zero, has dirty upper bits (not a clean
     * zero-padded EVM address), or does not match the OFT's live peer for the origin endpoint.
     */
    error InvalidOriginPeer();

    /**
     * @notice Reverts if the OFT is not a contract, its shared decimals differ from its own
     * token's, it reports a non-canonical interface/message-codec version, or - once a token
     * is pinned - it wraps a different token.
     */
    error InvalidOft();

    /**
     * @notice Reverts when an operation needs the compose transport and it is not configured.
     */
    error ComposeTransportNotConfigured();

    /**
     * @notice Returns the compose transport.
     * @return The transport; all-zero when not configured.
     */
    function getComposeTransport()
        external view
        returns (Transport memory);
}

contracts/userInterfaces/facets/IExecuto.content:
// SPDX-License-Identifier: MIT
pragma solidity >=0.8.4 <0.9;

/**
 * @title IExecutorsFacet
 * @notice Interface for the ExecutorsFacet contract.
 */
interface IExecutorsFacet {

    /**
     * @notice Emitted when the executor address is set.
     * @param executor The new executor address.
     */
    event ExecutorSet(
        address executor
    );

    /**
     * @notice Emitted when the executor fee is set.
     * @param executorFee The new executor fee.
     */
    event ExecutorFeeSet(
        uint256 executorFee
    );

    /**
     * @notice Reverts if the executor address is invalid.
     */
    error InvalidExecutor();

    /**
